param([Parameter(Mandatory)][ValidateSet('normal')][string]$Action,[switch]$ExecuteApproved)
Set-StrictMode -Version Latest;$ErrorActionPreference='Stop';$ProgressPreference='SilentlyContinue'
. "$PSScriptRoot/afternoon-runtime-helpers.ps1"
$stage='APPROVAL';$submitted=$false;$context=$null;$vars=$null
try{
 if(-not $ExecuteApproved){throw 'approval'};Import-Phase08SchedulerChildDefinitions
 $output=Assert-Phase08SchedulerOutputPath ("C:/Users/seong/AppData/Local/MetaAdsPhase08Evaluation/october16-v22-repeat-runtime-$Action-actual-20261016.json")
 $marker=Assert-Phase08SchedulerOutputPath ("C:/Users/seong/AppData/Local/MetaAdsPhase08Evaluation/october16-v22-repeat-runtime-$Action-attempt-20261016.json")
 $stage='IDENTITY';$pins=Get-Phase08SchedulerPins;$context=Read-Phase08ProtectedJson;Assert-Phase08SchedulerContext $context $pins
 if($pins.sourceSha -cne '0f790d901c949fc456dce6ab863b4bccca10a212b7c7b75afb03f52a0979fdc1'){throw 'source'}
 $stage='REAL_CLOCK';$now=[DateTimeOffset]::UtcNow;$start=[DateTimeOffset]'2026-10-16T03:30:00Z';$end=if($Action -ceq 'restart'){[DateTimeOffset]'2026-10-16T04:55:00Z'}else{[DateTimeOffset]'2026-10-16T14:50:00Z'}
 if($now -lt $start -or $now -ge $end){throw 'clock'}
 $stage='STOP_AND_LEASE';$sql="BEGIN READ ONLY;SET LOCAL statement_timeout=15000;SELECT current_database()='postgres' AND current_user='postgres' AND current_setting('transaction_read_only')='on' AS identity,(SELECT count(*)::int FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='phase08_meta_ads' AND c.relkind='r' AND c.relrowsecurity AND c.relforcerowsecurity) AS tables,(SELECT count(*)::int FROM daily_data_sync_ops.settings WHERE singleton AND stopped AND target_id='phase08-full-app' AND origin='https://phase08-daily-data-sync-production.up.railway.app') AS stopped,(SELECT count(*)::int FROM cron.job WHERE jobname LIKE 'daily-data-sync-08-%') AS jobs,(SELECT count(*)::int FROM cron.job WHERE jobname LIKE 'daily-data-sync-08-%' AND active) AS active,(SELECT count(*)::int FROM phase08_meta_ads.sync_leases WHERE expires_at>clock_timestamp()) AS leases,(SELECT count(*)::int FROM phase08_meta_ads.run_units u JOIN phase08_meta_ads.sync_runs r ON r.id=u.run_id WHERE r.request_key='schedule:phase08-meta:'||encode(sha256(convert_to('2026-10-16T03:30:00.000Z','UTF8')),'hex') AND r.connection_id='1277dc2a-ea20-41eb-8a1c-ab1bfcc564f6' AND r.trigger='SCHEDULED' AND r.from_date='2026-10-09' AND r.to_date='2026-10-15' AND u.status='SUCCEEDED') AS successes;COMMIT;"
 $rows=@(Invoke-Phase08Management -Action Query -Query $sql);if($rows.Count -ne 1){throw 'rows'};$r=$rows[0];if($r.identity -isnot [bool] -or -not $r.identity){throw 'identity'}
 foreach($pair in @(@('tables',68),@('stopped',1),@('jobs',149),@('active',149),@('leases',0))){$n=$pair[0];if(($r.$n -isnot [int] -and $r.$n -isnot [long]) -or $r.$n -ne $pair[1]){throw 'baseline'}}
 if(($r.successes -isnot [int] -and $r.successes -isnot [long]) -or $r.successes -lt 1 -or $r.successes -gt 7 -or ($Action -ceq 'restart' -and $r.successes -gt 6)){throw 'between-units'}
 $stage='COMMITTED_PROOF';$modes=if($Action -ceq 'restart'){@{sql='first-unit-sql';project='project-first-unit'}}else{@{sql='weekly-sql';project='project-weekly'};@{sql='cafe-sql';project='project-cafe'}}
 foreach($mode in $modes){$p=Invoke-Phase08ConfigurationChild "$PSScriptRoot/october16-repeat-proof.mjs" @{action=$mode.sql};if($p.sql -isnot [string] -or -not $p.sql.StartsWith('BEGIN READ ONLY;') -or -not $p.sql.EndsWith('COMMIT;')){throw 'proof-sql'};$pr=@(Invoke-Phase08Management -Action Query -Query $p.sql);$checked=Invoke-Phase08ConfigurationChild "$PSScriptRoot/october16-repeat-proof.mjs" @{action=$mode.project;rows=@($pr)};if($checked.verified -isnot [bool] -or -not $checked.verified){throw 'not-committed'}}
 $stage='LIVE_CONFIGURATION';$phase=if($Action -ceq 'normal'){'normal'}else{'test'};$profile=Invoke-Phase08ConfigurationChild "$PSScriptRoot/october16-repeat-profile-bridge.mjs" @{action='definitions';phase=$phase};$graph=Get-Phase08SchedulerGraphState $context $pins
 if($graph.scheduleEnabled -isnot [bool] -or -not $graph.scheduleEnabled -or $graph.featureEnabled -isnot [bool] -or -not $graph.featureEnabled -or $profile.state -cne 'PHASE08_OCTOBER16_DEFINITIONS' -or @($graph.appSchedules).Count -ne 3){throw 'profile'}
 foreach($d in $profile.definitions){$found=@($graph.appSchedules|Where-Object {$_.key -ceq $d.key});if($found.Count -ne 1 -or $found[0].connectionId -cne $d.connectionId -or $found[0].anchorAt -cne $d.anchorAt -or $found[0].windowMinutes -ne $d.windowMinutes){throw 'definitions'}}
 $service=Get-Phase08AfternoonRuntimeService $pins;if($service.latestDeployment.status -cnotin @('SUCCESS','SLEEPING') -or @($service.activeDeployments).Count -ne 1 -or $service.activeDeployments[0].id -cne $pins.deploymentId -or -not $service.latestDeployment.canRedeploy){throw 'service'}
 $null=Write-Phase08SchedulerPublicEvidence @{classification='OCTOBER16_SAME_IMAGE_REDEPLOY_PLANNED';action=$Action;observedAt=[DateTimeOffset]::UtcNow.ToString('o');sourceSha=$pins.sourceSha;previousDeploymentId=$pins.deploymentId;providerRequestsByController=0} $marker
 $stage='SINGLE_MUTATION';if([DateTimeOffset]::UtcNow -ge $end){throw 'clock'};$submitted=$true;$reply=Invoke-Phase08SchedulerGraph 'mutation($id:String!){deploymentRedeploy(id:$id,usePreviousImageTag:true){id}}' @{id=$pins.deploymentId};$newId=$reply.deploymentRedeploy.id
 if($newId -isnot [string] -or $newId -cnotmatch '^[a-f0-9]{8}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{12}$' -or $newId -ceq $pins.deploymentId){throw 'result'}
 $out=@{state='PHASE08_OCTOBER16_RUNTIME_OPERATION_SUBMITTED';action=$Action;observedAt=[DateTimeOffset]::UtcNow.ToString('o');sourceSha=$pins.sourceSha;previousDeploymentId=$pins.deploymentId;deploymentId=$newId;mutationCalls=1;actualCompletionVerified=$false;providerRequestsByController=0;databaseWrites=0;operatingChanges=0;retryPerformed=$false}
 $null=Write-Phase08SchedulerPublicEvidence $out $output;$out|ConvertTo-Json -Compress
}catch{@{state='PHASE08_OCTOBER16_RUNTIME_OPERATION_FAILED';stage=$stage;outcomeUncertain=$submitted;inspectBeforeRetry=$true;retryPerformed=$false;rawErrorSuppressed=$true}|ConvertTo-Json -Compress;exit 1}finally{$context=$null;$vars=$null;$reply=$null;$service=$null}
